style.css:
@-moz-document domain("roblox.com") {
.dark-theme .content {
    background-color: #00000000;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .section-content {
    background-color: #00000073;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .stack .stack-list .stack-row {
    background-color: #00000073;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .stack .card-list .card-item {
    background-color: #0000;
    border-radius: 5px;
}

.dark-theme .rbx-tab .rbx-tab-heading {
    background-color: #00000000;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .rbx-tabs-horizontal .nav-tabs {
    background-color: #000000b5;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .content {
    background-color: #00000000;
    color: #fff;
}

.dark-theme {
    background-color: #00000000;
    color: #fff;
}

.dark-theme .rbx-tabs-vertical .category-tabs .menu-vertical {
    background-color: #00000082;
    color: #fff;
    border-radius: 5px;
}

.dark-theme .asset-thumb-container {
    background-color: rgb(0 0 0 / 28%);
    border: 0;
}

.dark-theme .thumbnail-2d-container {
    border: 0;
    background-color: rgb(0 0 0 / 39%);
    border-color: #393b3d;
}

.dark-theme {
    color: #fff;
    background-image: url("https://cdn.phototourl.com/member/2026-09-24-8d9b6b48-1a31-4a24-84ce-52e9bc9de760.png") !important;
    background-repeat: no-repeat;
    background-size: 100% 100%;
    background-attachment: fixed;
}
}
